import{_ as o,o as c,c as d,a2 as t}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"内部调用链","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/call-chains.md","filePath":"zh/dev/call-chains.md"}'),r={name:"zh/dev/call-chains.md"};function s(a,e,i,l,n,_){return c(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="内部调用链" tabindex="-1">内部调用链 <a class="header-anchor" href="#内部调用链" aria-label="Permalink to &quot;内部调用链&quot;">​</a></h1><p>对阅读或修改内核时最重要的六条路径的解剖。每条都以带编号的 阶段呈现，附 触发 -&gt; 处理 -&gt; 影响 契约与拥有各阶段的文件。 地址、常量与错误字符串均取自源码；这里没有任何臆测。</p><h2 id="_1-execve-路径-运行一个程序" tabindex="-1">1. execve 路径（运行一个程序） <a class="header-anchor" href="#_1-execve-路径-运行一个程序" aria-label="Permalink to &quot;1. execve 路径（运行一个程序）&quot;">​</a></h2><p><strong>触发</strong>：ush 解析到一条非内建的命令行（或某程序直接调用 <code>SYS_EXECVE</code>，或 <code>job_create</code>/<code>run</code> 包装了它）。</p><ol><li><strong>ush 分发</strong>（<code>ocos/l1apps/ush/main.c</code>）：切分该行 （展开 <code>$VAR</code>、处理管道/重定向），argv 装配进静态存储， 子进程中 <code>fork()</code> 然后 <code>execve(name, argv)</code>；父进程 <code>wait4</code>（前台）或记录一个作业槽位（后台 <code>&amp;</code>）。</li><li><strong>系统调用</strong>（<code>SYS_EXECVE</code> = 11，<code>core_usermode.c</code>）： 经 <code>core_userprog_lookup(name, &amp;size)</code> 查找名字 —— 在 生成的 <code>OC_USERPROGS[]</code> 注册表（<code>userprogs_data.h</code>， 284 个条目，各是自己的 gzip 流；唯独 ush 保持原始， 因为 <code>OC_L1_APP_DECL</code> 需要编译期 ELF 指针）之上做共享 的名字到内嵌 ELF 查找。</li><li><strong>惰性解压</strong>（<code>core_usermode.c</code> + <code>core_lib_gzip.c</code>）： 在一个应用的第一次 exec 时，gzip blob 被充气进一个 每程序堆缓存（<code>g_prog_cache[OC_USERPROGS_COUNT]</code>）； 之后的 exec 复用缓存的原始 ELF。解压器是完整的 RFC 1951/1952 实现（stored/fixed/dynamic Huffman、 可恢复的流式喂入、CRC32+ISIZE 校验）。</li><li><strong>ELF 加载</strong>（<code>core_usermode.c</code>）：ET_EXEC 映射到固定 用户布局（代码基址 0x400000）；ET_DYN（PIE）路由到 加载器家族（<code>services/loader</code>）：解析 PT_INTERP，把 ld.so 映射到固定的 0x10000000，主程序加上已知 .so 镜像落在各自的递增基址，经 <code>user_aslr_page_slice</code> 做 ASLR（两次 rdtsc 采样 + splitmix64 终结器），然后 控制权转给 ld.so 的入口 —— ld.so（ring 3）解析 .dynamic、修补 GOT/PLT 并跳转到 <code>app_main</code> 的调用者 <code>_start</code>（共享的 <code>l1_crt_entry.asm</code> 读 <code>[rsp]</code>=argc / <code>[rsp+8]</code>=argv、对齐、调用 <code>app_main</code>）。</li><li><strong>地址空间构造</strong>：全新 PML4；拷贝内核 PML4[1..3]； PRIVATE PDPT[0]+PD0（内核 512 x 2 MiB 大页 PDE 的 副本）；PD0[2]（0x400000-0x600000）替换为一个<em>空</em> PT （绝不预填内核物理页）；栈顶 0x40000000（64 KiB）。</li><li><strong>调度</strong>：新任务占用 16 个用户进程槽位 / 32 个任务槽位 之一，默认优先级 15；父进程的 wait4 在退出后由统一 回收器（<code>user_process_reap_resources</code>）运行时完成 —— 它从 tick 与 yield 两处、在 cli 之下运行 （BUG-0282 双重释放修复）。</li></ol><p><strong>影响</strong>：首系统调用门禁 —— 默认 L1 入口 （pid == <code>g_l1_entry_pid</code>）的第一个系统调用翻转 <code>OCST_STAGE_L1_READY</code>，即热路径上的一次性启动状态加载。</p><h2 id="_2-一次-l1svc-调用的端到端" tabindex="-1">2. 一次 L1SVC 调用的端到端 <a class="header-anchor" href="#_2-一次-l1svc-调用的端到端" aria-label="Permalink to &quot;2. 一次 L1SVC 调用的端到端&quot;">​</a></h2><p><strong>触发</strong>：一个 ring-3 包装调用 <code>syscall5(SYS_L1SVC, cat, op, arg, out, cap)</code>。</p><ol><li><strong>ring-3 包装</strong>（<code>ocos/interface/l1_api_syscall.h</code>）： <code>l1svc_main</code> 把 argv 拼成 256 字节参数行；<code>out</code> 是 静态 32 KiB BSS 缓冲区。</li><li><strong>入口</strong>：<code>int 0x80</code> -&gt; IDT 向量 128（DPL=3 门）-&gt; stub 压入 15 个 GPR + 伪造错误码 -&gt; <code>arch_isr_dispatch</code> -&gt; <code>core_syscall_dispatch(frame)</code>； <code>r8</code>（第 5 参，cap）被暂存进 <code>g_syscall_arg5</code>。</li><li><strong>sys_l1svc</strong> （<code>services/sysapi/src/svc_sysapi_syscall.c</code>）：校验 out/cap（1..32768，或 0/0 的发后即忘拼法），把 <code>arg</code> 拷入 256 字节内核缓冲区（cat OCIRE 为 4096），<code>sti</code>。</li><li><strong>服务分发</strong>（<code>services/svc_framework.c</code>）： <code>svc_framework_dispatch(cat, op, arg, out, cap)</code> 扫描 <code>s_svcs[64]</code> 找精确匹配的类别字符串并调用该服务的 <code>l1_dispatch(op, arg, out, cap)</code>。</li><li><strong>kcap 捕获</strong>（<code>kernel/core_kcap.c</code>）：捕获式 op 运行在 <code>core_kcap_run_fn(fn, arg, out, cap)</code> 之内 —— 激活期间 捕获钩子<em>就是</em>控制台钩子（唯一槽位）：字符收集进 <code>out</code>，帧缓冲绘制与串口 tee 被压制，捕获可叠至 4 层 （只有最内层的活跃捕获接受数据），溢出被标记、绝不 静默截断；最后一个捕获结束时重装基础钩子（kmain 安装的启动串口 tee）。</li><li><strong>返回</strong>：<code>cli</code>；服务自身的非零退出状态仍算调用成功 —— 只有不可路由的 cat/op（或 rc&lt;0 且 out 为空）返回 -1； 否则回拷 NUL 结尾的文本并返回 0。信号投递（若有） 发生在处理函数之后、<code>iretq</code> 之前。</li></ol><p><strong>影响</strong>：这唯一的一扇门承载全部 208 个 op；<code>sti/cli</code> 窗口正是让 op 体内的设备等待循环可以 tick 驱动、而不是 冻住整台机器的原因。</p><h2 id="_3-网络接收路径" tabindex="-1">3. 网络接收路径 <a class="header-anchor" href="#_3-网络接收路径" aria-label="Permalink to &quot;3. 网络接收路径&quot;">​</a></h2><p><strong>触发</strong>：一帧到达 NIC（或 10 ms 软定时器触发轮询）。</p><ol><li><strong>驱动层</strong>：e1000 环（<code>e1000_desc_t</code>，2048 字节缓冲区）/ virtio-net 队列（<code>net_virtq_*</code>，VIRTIO_BUF_SIZE 2048）/ WP-10b 框架网卡暴露 <code>driver_nic_ops_t.recv(dev, buf, maxlen)</code> —— 轮询式， 返回一帧（&gt;0）、无帧时 0、出错 -1。</li><li><strong>轮询引擎</strong>（<code>services/net/src/svc_net_core.c</code>）： <code>net_start_timer()</code> 注册 <code>core_timer_register_periodic(net_timer_cb, NULL, 10)</code> —— 每 <strong>10 ms</strong> 一次 <code>net_poll</code>；<code>net_poll</code> 也在 <code>net_recv</code> 的等待循环中从线程上下文被调用（套接字读 阻塞得富有产出）。</li><li><strong>以太网解复用</strong>（<code>eth_hdr_t</code>，类型 ARP 0x0806 / IP 0x0800）：ARP 喂给 16 项缓存 （<code>g_arp_cache[ARP_CACHE_SIZE]</code>）；IP 继续。</li><li><strong>IP</strong>（<code>net_ip_hdr_t</code>）：分片重组 （<code>IP_FRAG_MAX_FRAGS 8</code>，8*1480 缓冲区，5 秒超时； 重组/丢弃/驱逐统计 —— BUG-0210）；坏校验和数据报 被计数并丢弃（<code>net_rx_bad_checksum</code>，BUG-0072）。</li><li><strong>Netfilter INPUT 链</strong>（<code>g_nf_rules[NF_MAX_RULES=32]</code>， conntrack <code>g_nf_ct[32]</code>，60 秒超时； ACCEPT/DROP/REJECT，NEW/ESTABLISHED）：DROP 在此终结 遍历并计数。</li><li><strong>L4 解复用</strong>：ICMP echo -&gt; ping 应答器；UDP -&gt; 32 项 处理程序表（<code>g_udp_handlers</code>，DHCP 68/67、DNS 53 客户端）；TCP -&gt; 32 连接引擎（内核堆上的 <code>net_tcp_conn_t</code>，约 520 KiB）：定序、SACK 块、乱序 缓存、CUBIC 拥塞窗口（RFC 8312 整数数学， <code>cubic_state_t</code>）、带 srtt/rttvar + Karn 规则的 RTO、 时间戳、窗口缩放。</li><li><strong>套接字</strong>（<code>g_sockets[MAX_SOCKETS=32]</code>，堆）： <code>SYS_NETRECV</code> 找到该套接字的 rx 缓冲区（TCP rx_buf 8192 —— WP-09-FIX BUG-002 之前是 2048）并拷贝到用户 缓冲区；被阻塞的读方被唤醒。</li></ol><p><strong>影响</strong>：<code>netstat</code>/<code>tcpstats</code> 读的正是这条链所改动的 那些表（<code>net_stats_t</code> 计数器、<code>g_tcp_conns[]</code> CUBIC 内部状态）；<code>net_e1000_resume()</code> 在 ACPI S3 唤醒后重放 legacy e1000 寄存器编程。</p><h2 id="_4-块-i-o-路径" tabindex="-1">4. 块 I/O 路径 <a class="header-anchor" href="#_4-块-i-o-路径" aria-label="Permalink to &quot;4. 块 I/O 路径&quot;">​</a></h2><p><strong>触发</strong>：一个文件系统（或分区解析器，或安装器）读或写 扇区。</p><ol><li><strong>fs 层</strong>（services/fs）：FAT32/exFAT/ext4 经 <code>driver_block_read/write_sectors</code>（下标形式）或指针 形式 <code>driver_block_read/write(dev, lba, count, buf)</code> 读写元数据与数据 —— 绝不直连驱动。</li><li><strong>缓存门</strong>（<code>services/block/src/svc_block_cache.c</code>）： 按 (dev_idx, lba) 咨询 64 槽位 LRU 写回缓存 （<code>driver_block_cache_slot_t</code>，共 32 KiB）；命中更新 <code>last_used</code>；未命中挑选牺牲者 —— 先空槽、再按 LRU 顺序，且脏牺牲者只在其写回<em>成功</em>后才被释放 （BUG-0116：旧代码忽略写回返回值并静默丢数据）； 若所有脏槽位都失败，调用方退回写通。</li><li><strong>设备分发</strong>（<code>svc_block_drivers.c</code>）：运行设备的 <code>driver_block_ops_t.read/write</code>；<code>driver_block_flush(dev)</code> 在推完脏扇区后调用 <code>.flush</code>（可选）（ATA FLUSH CACHE / NVMe Flush / virtio-blk FLUSH）。</li><li><strong>驱动</strong>（drivers/storage）：ATA PIO LBA28/LBA48 或 Bus-Master DMA（PRDT 在 BAR4，保留 PIO 回退）；AHCI 经每端口 4 KiB 页对齐跳板缓冲执行 READ/WRITE DMA EXT， 按至多 8 扇区分块（每块一条 PRDT 项）；NVMe Read/Write （0x02/0x01）以 64 位 PRP 走两对 I/O 队列； virtio-blk 请求/应答描述符。</li><li><strong>DMA 纪律</strong>：传输缓冲区遵守堆的 32 字节头/16 字节 对齐契约（奇偶 40 字节头 bug 曾把 ATA-DMA 缓冲区偏移 了 8）；xHCI 在探测与每次传输时拒绝 4 GiB 以上的 DMA。</li><li><strong>保护门</strong>（OCIRE 嵌入）：嵌入激活时，经覆盖设备进行 的每一次写都被拒绝；内核内部的 <code>driver_block_read/write_sectors_trusted</code> 是唯一的 写方（嵌入服务与分区子项）；绝不可从 ring 3 调用。</li></ol><p><strong>影响</strong>：<code>sync</code>（op BLK 11）端到端刷洗这条链； <code>dskstat</code>/<code>lsblk</code> 报告每设备统计与缓存计数器； <code>power shutdown</code> 在 S5 之前刷洗缓存。</p><h2 id="_5-崩溃路径" tabindex="-1">5. 崩溃路径 <a class="header-anchor" href="#_5-崩溃路径" aria-label="Permalink to &quot;5. 崩溃路径&quot;">​</a></h2><p><strong>触发</strong>：无人认领的 ring-0 异常、一次 <code>kernel_panic</code> 调用、一次 <code>OC_ASSERT</code> 失败，或看门狗策略 PANIC。</p><ol><li><strong>向量入口</strong>（<code>arch_idt_stub.S</code> -&gt; <code>arch_exceptions.c</code>）： 先过嵌套 #PF 守卫（#PF 处理中再遇 #PF 会打印 <code>*** NESTED #PF INSIDE EXCEPTION HANDLER - HALTING ***</code> 并 cli;hlt）；L1 处理链（每向量 4 个，最近注册者先 运行）；#PF 路由到 <code>mem_vmm_handle_page_fault</code>（栈 增长；保护违例绝不重映射）；ring-3 来源的故障改走 SIGSEGV 投递 / kill 路径（向量 1/2/3 的 kill 运行在 专用退出栈上，保持 IST2 完好 —— BUG-0139）。</li><li><strong>panic 路由</strong>（<code>kernel_panic</code>/<code>kernel_panic_frame</code> -&gt; services/crash 经 <code>arch_set_panic_handlers</code> 安装的 处理程序）：#DF 被完全特判在分发器深度，仅一条静态 192 字节串口行（无记录、无转储、无刷洗 —— 见 KNOWN_ISSUES）；其他所有来源走完整路径。</li><li><strong>规范化 + 首条记录</strong>：CR3 切到内核地址空间，使 traceback/转储/堆读取安全； <code>klog_record(KLOG_FATAL, &quot;kernel&quot;, reason)</code> 写入环形 日志（仅环形 —— 该深度没有 VFS）。</li><li><strong>横幅 + 快照</strong>（<code>svc_crash_core.c</code>）：串口为权威 （VGA 红底尽力而为）： <code>*** KERNEL PANIC: &lt;reason&gt; [task=&lt;name&gt;] ***</code>、内核 身份行、<code>source: exception &lt;n&gt; (&lt;name&gt;) err=0x...</code>、 任务行、寄存器转储（4x4 网格 r15..rax + rip/cs/ss/rflags/rsp/int/err，#PF 加 cr2，外加 cr3）、 经 <code>looks_like_code</code> 过滤的 rbp 链 + 栈扫描回溯。 栈耗尽会被归因：守卫页 #PF 或耗尽栈 #DF 会在 reason 中点名任务。</li><li><strong>OCDUMP01 核心转储</strong>（<code>core_dump_save</code>）：填充启动 保留缓冲区（<code>core_dump_alloc()</code> 已在 kmain 步骤 16a 一次性 kmalloc —— 此后 kmalloc 可能失败或堆可能 损坏，panic 路径只碰保留缓冲区）：头、22 个 u64 寄存 器（帧或活体快照）、任务块、4 KiB 栈窗口、CR3 + PML4 自扫描 PTE 计数；持久化到 <code>/var/crash/core.dump</code> （ramfs rootfs 或 FAT32）；没有文件系统时前 2048 字节以十六进制转储到串口，数据不丢失。</li><li><strong>Crashlog 环</strong>（<code>crashlog_record</code>）：向 32 槽位环 写入一条 <code>crashlog_entry_t</code>（向量或合成来源 32..36； ring 0/3；err/rip/rsp/cr2；tid/pid/task；jiffies + rtc_epoch）；<code>crashlog_flush()</code> 把一切追加到 <code>/var/log/crash.log</code>。</li><li><strong>策略</strong>：已注册的 panic 处理程序（至多 4 个，最近 注册者先运行）可以认领恢复 （<code>*** panic handler claimed recovery - resuming ***</code>、 <code>*** CONTAINED: ... - isolated, kernel continues ***</code> —— TUI 守卫机制）；否则 <code>CRASH_POLICY_HALT</code>（默认， cli + 安全 hlt）或 <code>CRASH_POLICY_REBOOT</code>（8042 + 0xCF9），可用 <code>crashtest policy [halt|reboot]</code> 在线 切换。</li></ol><p><strong>OCBL/OCIRE 继电器（启动失败）</strong>：让启动状态心跳停摆的 挂死会停止喂 6300ESB -&gt; 硬复位 -&gt; OCBL 读 0x98000 状态区， 判定（沉默 &gt;= 8 秒、无 CLEAN 标记），在 0x9B000 写入 BOOT_FAILED 记录 -&gt; 下次启动自动启动 OCIRE -&gt; OCIRE 读 该记录并打印停滞点 + 修复建议。<em>用户请求的</em> OCIRE 启动 则改写 USER_REQUEST 记录。完整契约： <a href="./data-structures.html">data-structures.md</a> 第 8 节、 <a href="./../internals/crash-dump.html">../internals/crash-dump.md</a>。</p><h2 id="_6-ota-安装路径" tabindex="-1">6. OTA 安装路径 <a class="header-anchor" href="#_6-ota-安装路径" aria-label="Permalink to &quot;6. OTA 安装路径&quot;">​</a></h2><p><strong>触发</strong>：<code>update</code>（裸在线流程）、<code>update --local &lt;pkg&gt;</code> （离线），或更新向导的第 5 步确认。</p><ol><li><strong>检查</strong>（<code>L1SVC_OTA_CHECKUPDATE</code> -&gt; <code>ota_update_check</code>）： 抓取 <code>update.json</code>（按配置的 <code>update_url</code> 走 HTTP 或 HTTPS），比较 <code>version</code> 与 <code>build</code>（<code>OC_KERNEL_BUILD</code>， 数字比较 —— BUG-0347；构建 id 是 <code>git rev-list --count HEAD + 21</code>，因此在已发布 id 之上 保持单调）。锚点：&quot;Current version is up to date.&quot; / &quot;New version available.&quot;。</li><li><strong>下载</strong>（<code>ota_update_download</code>）：经 TCP/TLS 流式 下载到 <code>/data/update-pkg.tar.gz</code>（默认；临时 <code>/tmp/update-pkg.tar.gz</code>）；失败打印 <code>&quot;update: download failed: &quot;</code>。</li><li><strong>校验</strong>：包 SHA256 对照清单（<code>update_verify</code>）； 清单还携带按归档顺序拼接的成员体之上的载荷 sha256。</li><li><strong>解码</strong>：解压（RFC 1952/1951，校验 CRC32+ISIZE）+ 解包（带校验和验证的流式 ustar、GNU &#39;L&#39; 长名、pax 跳过）直接写入<strong>非活动槽位</strong>（运行 A 时写 B； <code>ota_ab_target_slot()</code> —— 从 ISO 运行时 &quot;update: cannot determine target slot (not booted from A/B?)&quot;）。</li><li><strong>写启动标志</strong>：创建 <code>/boot/next_B</code>；新槽位的内核 <strong>在启动时悲观地</strong>写入 <code>/boot/bootfail_B</code>，仅当系统 完全起来后才移除（kmain 步骤 16c 的 <code>ota_update_confirm_boot</code>）；<code>ok_B</code> 标记已确认的 B。 启动选择（grub.cfg）：存在 <code>next_B</code> 且无 <code>bootfail_B</code> -&gt; 启动 B；两者皆在 -&gt; 回滚到 A；<code>ok_B</code> -&gt; B；否则 A。启动尝试预算：GRUB 环境块 <code>/boot/grub/grubenv</code> （1024 字节，<code>ab_attempts</code>），<code>OC_AB_MAX_ATTEMPTS 3</code>， A 完成启动或 B 确认时重置。</li><li><strong>重启</strong>：流程打印 &quot;reboot required&quot;；<code>POWER/REBOOT</code> （8042 + 0xCF9）落到新槽位；回滚 （<code>L1SVC_OTA_ROLLBACK</code>）清除标志。</li></ol><p><strong>影响</strong>：失败的写永远不碰运行中的槽位 —— 活动系统一直 服务到翻转那一刻；A/B 磁盘布局（p1 boot/flags 32 MB FAT32 + p2 槽位 A 128M + p3 槽位 B 128M + p4 /data）由 <code>abdisk</code> 创建，其后再跑一遍 <code>ota_ab_rescan()</code>。完整页面： <a href="./../internals/ota-ab.html">../internals/ota-ab.md</a>。</p>',26)])])}const u=o(r,[["render",s]]);export{p as __pageData,u as default};
